std::string read_file(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

void write_file(const std::string& path, const std::string& content) {
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    if (out) out << content;
}

std::string escape_json(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default: out += c;
        }
    }
    return out;
}

std::string unescape_json(const std::string& s) {
    std::string out;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            char n = s[++i];
            switch (n) {
                case 'n': out += '\n'; break;
                case 'r': out += '\r'; break;
                case 't': out += '\t'; break;
                default: out += n;
            }
        } else {
            out += s[i];
        }
    }
    return out;
}

bool find_field(const std::string& obj, const std::string& key, std::string& out) {
    std::string needle = "\"" + key + "\"";
    size_t p = obj.find(needle);
    if (p == std::string::npos) return false;
    p = obj.find(':', p + needle.size());
    if (p == std::string::npos) return false;
    p = obj.find('"', p);
    if (p == std::string::npos) return false;
    std::string raw;
    for (size_t q = p + 1; q < obj.size(); ++q) {
        if (obj[q] == '\\' && q + 1 < obj.size()) {
            raw += obj[q];
            raw += obj[++q];
        } else if (obj[q] == '"') {
            out = unescape_json(raw);
            return true;
        } else {
            raw += obj[q];
        }
    }
    return false;
}

std::vector<std::string> extract_objects(const std::string& content) {
    std::vector<std::string> objs;
    bool in_str = false;
    int depth = 0;
    size_t start = 0;
    for (size_t i = 0; i < content.size(); ++i) {
        char c = content[i];
        if (in_str) {
            if (c == '\\') {
                ++i;
            } else if (c == '"') {
                in_str = false;
            }
            continue;
        }
        if (c == '"') {
            in_str = true;
        } else if (c == '{') {
            if (depth == 0) start = i;
            ++depth;
        } else if (c == '}') {
            if (depth > 0) --depth;
            if (depth == 0) objs.push_back(content.substr(start, i - start + 1));
        }
    }
    return objs;
}

std::string objs_to_array(const std::vector<std::string>& objs) {
    std::string out = "[";
    for (size_t i = 0; i < objs.size(); ++i) {
        if (i) out += ",";
        out += objs[i];
    }
    out += "]";
    return out;
}

std::string gen_salt(size_t bytes) {
    static const char* hex = "0123456789abcdef";
    std::random_device rd;
    std::mt19937_64 gen(rd());
    std::uniform_int_distribution<int> dist(0, 255);
    std::string s;
    s.reserve(bytes * 2);
    for (size_t i = 0; i < bytes; ++i) {
        int v = dist(gen);
        s += hex[(v >> 4) & 0xF];
        s += hex[v & 0xF];
    }
    return s;
}

}

namespace auth {

std::string sha256_hex(const std::string& msg) {
    uint32_t h[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                     0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
    uint64_t bitlen = static_cast<uint64_t>(msg.size()) * 8;

    std::vector<uint8_t> data(msg.begin(), msg.end());
    data.push_back(0x80);
    while (data.size() % 64 != 56) data.push_back(0x00);
    for (int i = 7; i >= 0; --i) data.push_back(static_cast<uint8_t>((bitlen >> (i * 8)) & 0xFF));

    for (size_t off = 0; off < data.size(); off += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; ++i) {
            w[i] = (static_cast<uint32_t>(data[off + i * 4]) << 24) |
                   (static_cast<uint32_t>(data[off + i * 4 + 1]) << 16) |
                   (static_cast<uint32_t>(data[off + i * 4 + 2]) << 8) |
                   (static_cast<uint32_t>(data[off + i * 4 + 3]));
        }
        for (int i = 16; i < 64; ++i) {
            uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }
        uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];
        for (int i = 0; i < 64; ++i) {
            uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            uint32_t ch = (e & f) ^ ((~e) & g);
            uint32_t t1 = hh + S1 + ch + K[i] + w[i];
            uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t t2 = S0 + maj;
            hh = g; g = f; f = e; e = d + t1;
            d = c; c = b; b = a; a = t1 + t2;
        }
        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }

    std::ostringstream ss;
    ss << std::hex << std::setfill('0');
    for (int i = 0; i < 8; ++i) ss << std::setw(8) << h[i];
    return ss.str();
}

void ensure_file(const std::string& path, const std::string& defaultContent) {
    std::string content = read_file(path);
    std::string trimmed;
    for (char c : content)
        if (c != ' ' && c != '\n' && c != '\r' && c != '\t') trimmed += c;
    if (trimmed.empty()) write_file(path, defaultContent);
}

bool register_user(const std::string& usersFile,
                   const std::string& username,
                   const std::string& password,
                   std::string& err) {
    if (username.empty()) {
        err = "Username cannot be empty";
        return false;
    }
    ensure_file(usersFile, "[]");
    std::string content = read_file(usersFile);
    std::vector<std::string> objs = extract_objects(content);

    for (const auto& obj : objs) {
        std::string existing;
        if (find_field(obj, "username", existing) && existing == username) {
            err = "Username already exists";
            return false;
        }
    }

    std::string salt = gen_salt(16);
    std::string hash = sha256_hex(salt + password);
    std::string entry = "{\"username\":\"" + escape_json(username) +
                        "\",\"salt\":\"" + salt +
                        "\",\"hash\":\"" + hash + "\"}";
    objs.push_back(entry);
    write_file(usersFile, objs_to_array(objs));
    return true;
}

bool verify_user(const std::string& usersFile,
                 const std::string& username,
                 const std::string& password) {
    std::string content = read_file(usersFile);
    std::vector<std::string> objs = extract_objects(content);
    for (const auto& obj : objs) {
        std::string u, salt, hash;
        if (find_field(obj, "username", u) && u == username &&
            find_field(obj, "salt", salt) && find_field(obj, "hash", hash)) {
            return sha256_hex(salt + password) =[secret redacted]
        }
    }
    return false;
}

bool write_session(const std::string& sessionFile, const std::string& username) {
    write_file(sessionFile, "{\"last_user\": \"" + escape_json(username) + "\"}");
    return true;
}

}

