namespace friends {

std::string friends_path(const std::string& username) {
    return "data/friends_" + username + ".json";
}

std::vector<Friend> load(const std::string& path) {
    std::vector<Friend> list;
    std::string content = read_file(path);
    for (const auto& obj : extract_objects(content)) {
        Friend f;
        if (find_field(obj, "user", f.user)) {
            if (!find_field(obj, "status", f.status)) f.status = "offline";
            if (f.status != "online" && f.status != "offline") f.status = "offline";
            list.push_back(f);
        }
    }
    return list;
}

bool exists(const std::string& path, const std::string& username) {
    for (const auto& f : load(path)) {
        if (f.user == username) return true;
    }
    return false;
}

bool add(const std::string& path, const std::string& username) {
    if (username.empty()) return false;
    std::vector<Friend> list = load(path);
    for (const auto& f : list) {
        if (f.user == username) return false;
    }
    list.push_back(Friend{username, "offline"});
    write_file(path, to_json_array(list));
    return true;
}

bool remove(const std::string& path, const std::string& username) {
    std::vector<Friend> list = load(path);
    std::vector<Friend> kept;
    bool removed = false;
    for (const auto& f : list) {
        if (f.user == username) {
            removed = true;
        } else {
            kept.push_back(f);
        }
    }
    if (removed) write_file(path, to_json_array(kept));
    return removed;
}

std::string to_json_array(const std::vector<Friend>& list) {
    std::string out = "[";
    for (size_t i = 0; i < list.size(); ++i) {
        if (i) out += ",";
        out += object_json(list[i].user, list[i].status);
    }
    out += "]";
    return out;
}

}

