#include "auth.h"
#include "friends.hpp"

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

namespace {

std::string read_text(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::string trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

std::string upper(const std::string& s) {
    std::string out = s;
    for (char& c : out) {
        if (c >= 'a' && c <= 'z') c = static_cast<char>(c - 'a' + 'A');
    }
    return out;
}

std::string extract_string_field(const std::string& obj, const std::string& key) {
    std::string needle = "\"" + key + "\"";
    size_t p = obj.find(needle);
    if (p == std::string::npos) return "";
    p = obj.find(':', p + needle.size());
    if (p == std::string::npos) return "";
    p = obj.find('"', p);
    if (p == std::string::npos) return "";
    std::string out;
    for (size_t q = p + 1; q < obj.size(); ++q) {
        if (obj[q] == '\\' && q + 1 < obj.size()) {
            out += obj[q];
            out += obj[++q];
        } else if (obj[q] == '"') {
            break;
        } else {
            out += obj[q];
        }
    }
    return out;
}

void show_main_menu() {
    std::cout << "[1] Register" << std::endl;
    std::cout << "[2] Login" << std::endl;
    std::cout << "[3] Exit" << std::endl;
}

void show_friend_menu() {
    std::cout << "[A] Add Friend" << std::endl;
    std::cout << "[R] Remove Friend" << std::endl;
    std::cout << "[L] List Friends" << std::endl;
    std::cout << "[C] Choose Friend" << std::endl;
    std::cout << "[Q] Logout" << std::endl;
}

void run_friend_session(const std::string& username,
                        const std::string& sessionFile) {
    (void)sessionFile;
    const std::string path = friends::friends_path(username);
    auth:[secret redacted]

    std::cout << "Welcome " << username << std::endl;

    while (true) {
        show_friend_menu();
        std::cout << "Action: " << std::flush;
        std::string choice;
        if (!std::getline(std::cin, choice)) break;
        std::string c = upper(trim(choice));

        if (c == "A") {
            std::cout << "Friend: " << std::flush;
            std::string name;
            if (!std::getline(std::cin, name)) break;
            name = trim(name);
            if (name.empty()) {
                std::cout << "Friend name cannot be empty" << std::endl;
            } else if (friends::add(path, name)) {
                std::cout << "Friend added" << std::endl;
            } else {
                std::cout << "Friend already exists" << std::endl;
            }
        } else if (c == "R") {
            std::cout << "Friend: " << std::flush;
            std::string name;
            if (!std::getline(std::cin, name)) break;
            name = trim(name);
            if (friends::remove(path, name)) {
                std::cout << "Friend removed" << std::endl;
            } else {
                std::cout << "Friend not found" << std::endl;
            }
        } else if (c == "L") {
            std::vector<friends::Friend> list = friends::load(path);
            for (const auto& f : list) {
                std::cout << "  - " << f.user << " [" << f.status << "]" << std::endl;
            }
        } else if (c == "C") {
            std::cout << "Friend: " << std::flush;
            std::string name;
            if (!std::getline(std::cin, name)) break;
            name = trim(name);
            if (!friends::exists(path, name)) {
                std::cout << "Friend not found" << std::endl;
            } else {
                std::cout << "--- Chat with " << name << " ---" << std::endl;
                while (true) {
                    std::string line;
                    if (!std::getline(std::cin, line)) break;
                    if (line == "/back") break;
                }
            }
        } else if (c == "Q") {
            std::cout << "Logged out" << std::endl;
            break;
        } else {
            std::cout << "Invalid choice" << std::endl;
        }
    }
}

}

int main(int argc, char** argv) {
