namespace {

std::string trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

std::string read_file(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

void write_file(const std::string& path, const std::string& content) {
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    if (out) out << content;
}

std::string escape_json(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default: out += c;
        }
    }
    return out;
}

std::vector<std::string> parse_string_array(const std::string& content) {
    std::vector<std::string> items;
    size_t i = 0;
    while (i < content.size()) {
        if (content[i] == '"') {
            std::string raw;
            ++i;
            while (i < content.size() && content[i] != '"') {
                if (content[i] == '\\' && i + 1 < content.size()) {
                    char n = content[i + 1];
                    switch (n) {
                        case 'n': raw += '\n'; break;
                        case 'r': raw += '\r'; break;
                        case 't': raw += '\t'; break;
                        case '"': raw += '"'; break;
                        case '\\': raw += '\\'; break;
                        default: raw += n; break;
                    }
                    i += 2;
                } else {
                    raw += content[i++];
                }
            }
            items.push_back(raw);
            if (i < content.size()) ++i;
        } else {
            ++i;
        }
    }
    return items;
}

}

namespace chat {

std::string iso_now() {
    std::time_t t = std::time(nullptr);
    std::tm tm{};
#if defined(_WIN32)
    localtime_s(&tm, &t);
#else
    localtime_r(&t, &tm);
#endif
    char buf[32];
    std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm);
    return std::string(buf);
}

std::string history_dir(const std::string& user) {
    return "data/history/" + user;
}

std::string history_path(const std::string& user, const std::string& friend_name) {
    return history_dir(user) + "/" + friend_name + ".log";
}

std::vector<std::string> load_replies(const std::string& path) {
    return parse_string_array(read_file(path));
}

std::vector<Message> load_history(const std::string& user,
                                  const std::string& friend_name) {
    std::vector<Message> msgs;
    std::ifstream in(history_path(user, friend_name), std::ios::binary);
    if (!in) return msgs;
    std::string line;
    while (std::getline(in, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.empty()) continue;
        size_t p1 = line.find(" | ");
        if (p1 == std::string::npos) continue;
        size_t p2 = line.find(" | ", p1 + 3);
        if (p2 == std::string::npos) continue;
        Message m;
        m.timestamp = line.substr(0, p1);
        m.sender = line.substr(p1 + 3, p2 - (p1 + 3));
        m.text = line.substr(p2 + 3);
        msgs.push_back(m);
    }
    return msgs;
}

void append_history(const std::string& user,
                    const std::string& friend_name,
                    const std::string& sender,
                    const std::string& text) {
    std::error_code ec;
    std::filesystem::create_directories(history_dir(user), ec);
    std::ofstream out(history_path(user, friend_name),
                      std::ios::binary | std::ios::app);
    if (!out) return;
    out << iso_now() << " | " << sender << " | " << text << "\n";
}

void clear_history(const std::string& user, const std::string& friend_name) {
    std::error_code ec;
    std::filesystem::create_directories(history_dir(user), ec);
    write_file(history_path(user, friend_name), "");
}

void print_history_page(const std::string& user,
                        const std::string& friend_name,
                        int page) {
    std::vector<Message> all = load_history(user, friend_name);
    std::reverse(all.begin(), all.end());
    if (page < 1) page = 1;
    int start = (page - 1) * 10;
    int end = std::min<int>(start + 10, static_cast<int>(all.size()));
    for (int i = start; i < end; ++i) {
        std::cout << all[i].timestamp << " | " << all[i].sender << " | "
                  << all[i].text << std::endl;
    }
}

void run_chat(const std::string& user,
              const std::string& friend_name,
              const std::string& replies_path) {
    std::vector<std::string> replies = load_replies(replies_path);
    std::cout << "--- Chat with " << friend_name << " ---" << std::endl;

    size_t idx = 0;
    std::string line;
    while (true) {
        std::cout << "> " << std::flush;
        if (!std::getline(std::cin, line)) break;

        std::string t = trim(line);
        if (t == "/exit" || t == "/back") break;

        if (t == "/clear") {
            clear_history(user, friend_name);
            std::cout << "History cleared" << std::endl;
            continue;
        }

        if (t.rfind("/history", 0) == 0) {
            std::string rest = trim(t.substr(std::string("/history").size()));
            int page = 1;
            if (!rest.empty()) {
                try {
                    page = std::stoi(rest);
                } catch (...) {
                    page = 1;
                }
            }
            print_history_page(user, friend_name, page);
            continue;
        }

        append_history(user, friend_name, user, line);
        std::string reply = replies.empty() ? "..." : replies[idx % replies.size()];
        ++idx;
        std::cout << "[Bot] " << reply << std::endl;
        append_history(user, friend_name, "bot", reply);
    }
}

std::string selftest_chat_loop_json(const std::string& replies_path) {
    std::vector<std::string> replies = load_replies(replies_path);
    std::string reply = replies.empty() ? "Hello!" : replies[0];

    std::vector<Message> msgs;
    msgs.push_back(Message{iso_now(), "user", "Hello"});
    msgs.push_back(Message{iso_now(), "bot", reply});
    msgs.push_back(Message{iso_now(), "user", "How are you?"});

    std::string out = "{ \"messages\": [";
    for (size_t i = 0; i < msgs.size(); ++i) {
        if (i) out += ", ";
        out += "{\"timestamp\": \"" + escape_json(msgs[i].timestamp) +
               "\", \"sender\": \"" + escape_json(msgs[i].sender) +
               "\", \"text\": \"" + escape_json(msgs[i].text) + "\"}";
    }
    out += "] }";
    return out;
}

}

