            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default: out += c;
        }
    }
    return out;
}

std::string read_string_token(const std::string& content, size_t& i) {
    std::string raw;
    const size_t n = content.size();
    if (i >= n || content[i] != '"') return raw;
    ++i;
    while (i < n && content[i] != '"') {
        if (content[i] == '\\' && i + 1 < n) {
            char c = content[i + 1];
            switch (c) {
                case 'n': raw += '\n'; break;
                case 'r': raw += '\r'; break;
                case 't': raw += '\t'; break;
                default: raw += c; break;
            }
            i += 2;
        } else {
            raw += content[i++];
        }
    }
    if (i < n) ++i;
    return raw;
}

std::vector<std::pair<std::string, std::string>> parse_map(const std::string& content) {
    std::vector<std::pair<std::string, std::string>> out;
    size_t i = 0;
    const size_t n = content.size();
    while (i < n) {
        if (content[i] != '"') {
            ++i;
            continue;
        }
        std::string key = read_string_token(content, i);
        while (i < n && content[i] != ':') ++i;
        if (i < n) ++i;
        while (i < n && (content[i] == ' ' || content[i] == '\t' ||
                         content[i] == '\n' || content[i] == '\r')) {
            ++i;
        }
        if (i < n && content[i] == '"') {
            std::string val = read_string_token(content, i);
            out.emplace_back(key, val);
        }
    }
    return out;
}

}

namespace alias {

std::string aliases_path(const std::string& user) {
    return "data/aliases_" + user + ".json";
}

std::vector<std::pair<std::string, std::string>> load(const std::string& user) {
    return parse_map(read_file(aliases_path(user)));
}

std::string resolve(const std::string& user, const std::string& friend_name) {
    for (const auto& kv : load(user)) {
        if (kv.first == friend_name) return kv.second;
    }
    return friend_name;
}

bool set(const std::string& user,
         const std::string& friend_name,
         const std::string& alias_name) {
    if (friend_name.empty() || alias_name.empty()) return false;
    std::vector<std::pair<std::string, std::string>> map = load(user);
    bool found = false;
    for (auto& kv : map) {
        if (kv.first == friend_name) {
            kv.second = alias_name;
            found = true;
        }
    }
    if (!found) map.emplace_back(friend_name, alias_name);

    std::string out = "{";
    for (size_t i = 0; i < map.size(); ++i) {
        if (i) out += ",";
        out += "\"" + escape_json(map[i].first) + "\": \"" +
               escape_json(map[i].second) + "\"";
    }
    out += "}";
    write_file(aliases_path(user), out);
    return true;
}

std::string to_json_array(const std::string& user) {
    std::vector<std::pair<std::string, std::string>> map = load(user);
    std::string out = "[";
    for (size_t i = 0; i < map.size(); ++i) {
        if (i) out += ", ";
        out += "{\"friend\": \"" + escape_json(map[i].first) +
