namespace {

std::string lower(const std::string& s) {
    std::string o = s;
    for (char& c : o) {
        if (c >= 'A' && c <= 'Z') c = static_cast<char>(c - 'A' + 'a');
    }
    return o;
}

std::string strip_cr(std::string s) {
    if (!s.empty() && s.back() == '\r') s.pop_back();
    return s;
}

std::string escape_json(const std::string& s) {
    std::string out;
    for (char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default: out += c;
        }
    }
    return out;
}

}

namespace search {

std::string highlight(const std::string& text, const std::string& keyword) {
    if (keyword.empty()) return text;
    std::string lt = lower(text);
    std::string lk = lower(keyword);
    size_t p = lt.find(lk);
    if (p == std::string::npos) return text;
    return text.substr(0, p) + "[[" + text.substr(p, keyword.size()) + "]]" +
           text.substr(p + keyword.size());
}

std::vector<Hit> search_all(const std::string& user, const std::string& keyword) {
    std::vector<Hit> hits;
    if (keyword.empty()) return hits;
    const std::string lk = lower(keyword);
    const std::string dir = "data/history/" + user;

    std::error_code ec;
    if (!std::filesystem::exists(dir, ec)) return hits;

    for (const auto& entry : std::filesystem::directory_iterator(dir, ec)) {
        if (!entry.is_regular_file()) continue;
        if (entry.path().extension().string() != ".log") continue;

        std::string friend_name = entry.path().stem().string();
        std::ifstream in(entry.path(), std::ios::binary);
        if (!in) continue;

        std::string line;
        while (std::getline(in, line)) {
            line = strip_cr(line);
            if (line.empty()) continue;
            size_t p1 = line.find(" | ");
            if (p1 == std::string::npos) continue;
            size_t p2 = line.find(" | ", p1 + 3);
            if (p2 == std::string::npos) continue;

            std::string date = line.substr(0, p1);
            std::string text = line.substr(p2 + 3);
            size_t pos = lower(text).find(lk);
            if (pos == std::string::npos) continue;

            Hit h;
            h.friend_name = friend_name;
            h.date = date;
            h.text = text;
            h.pos = pos;
            h.len = keyword.size();
            hits.push_back(h);
        }
    }
    return hits;
}

std::string to_json_array(const std::vector<Hit>& hits) {
    std::string out = "[";
    for (size_t i = 0; i < hits.size(); ++i) {
        if (i) out += ", ";
        out += "{\"friend\": \"" + escape_json(hits[i].friend_name) +
               "\", \"date\": \"" + escape_json(hits[i].date) +
               "\", \"text\": \"" + escape_json(hits[i].text) + "\"}";
    }
    out += "]";
    return out;
}

}

