                  ThreadSafeQueue<AutoMessage>& out,
                  double min_seconds = 3.0,
                  double max_seconds = 6.0);
    ~ChatSimulator();

    void start();
    void stop();

private:
    void worker(std::string friend_name, unsigned seed);

    std::vector<std::string> friends_;
    ThreadSafeQueue<AutoMessage>& out_;
    double min_seconds_;
    double max_seconds_;
    std::atomic<bool> running_{false};
