namespace {

struct InLine {
    std::string line;
    bool eof = false;
};

concurrency::ThreadSafeQueue<AutoMessage> g_messages;
concurrency::ThreadSafeQueue<InLine> g_input;
std::mutex g_out_mutex;
std::string g_prompt;
std::atomic<bool> g_reader_started{false};

const char* const kMessagePool[] = {
    "Hey, you around?",
    "What's up?",
    "Did you see the news?",
    "Let's catch up later.",
    "How's it going?",
    "Ping!",
    "Long time no chat.",
    "Are you free now?",
};

std::size_t kMessagePoolSize = sizeof(kMessagePool) / sizeof(kMessagePool[0]);

std::string pick_message(unsigned& seed) {
    seed = seed * 1103515245u + 12345u;
    return kMessagePool[(seed >> 16) % kMessagePoolSize];
}

}

namespace concurrency {

void start_input_reader() {
    bool expected = false;
    if (!g_reader_started.compare_exchange_strong(expected, true)) return;
    std::thread([] {
        std::string line;
        while (std::getline(std::cin, line)) {
            g_input.push(InLine{line, false});
        }
        g_input.push(InLine{"", true});
    }).detach();
}

void prompt(const std::string& p) {
    std::lock_guard<std::mutex> lock(g_out_mutex);
    g_prompt = p;
    std::cout << p << std::flush;
}

void print_line(const std::string& s) {
    std::lock_guard<std::mutex> lock(g_out_mutex);
    std::cout << s << std::endl;
}

bool read_line(std::string& out) {
    for (;;) {
        AutoMessage msg;
        if (g_messages.try_pop(msg)) {
            std::lock_guard<std::mutex> lock(g_out_mutex);
            std::cout << "[" << msg.friend_name << "] " << msg.text << std::endl;
            if (!g_prompt.empty()) std::cout << g_prompt << std::flush;
            continue;
        }
        InLine in;
        if (g_input.try_pop(in)) {
            if (in.eof) return false;
            out = in.line;
            return true;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
}

ThreadSafeQueue<AutoMessage>& message_queue() {
    return g_messages;
}

ChatSimulator::ChatSimulator(std::vector<std::string> friends,
                             ThreadSafeQueue<AutoMessage>& out,
                             double min_seconds,
                             double max_seconds)
    : friends_(std::move(friends)),
      out_(out),
      min_seconds_(min_seconds),
      max_seconds_(max_seconds) {}

ChatSimulator::~ChatSimulator() {
    stop();
}

void ChatSimulator::start() {
    if (running_.exchange(true)) return;
    threads_.clear();
    for (std::size_t i = 0; i < friends_.size(); ++i) {
        unsigned seed = static_cast<unsigned>(i * 2654435761u + 1013904223u);
        threads_.emplace_back(&ChatSimulator::worker, this, friends_[i], seed);
    }
}

void ChatSimulator::stop() {
    if (!running_.exchange(false)) return;
    for (auto& t : threads_) {
        if (t.joinable()) t.join();
    }
    threads_.clear();
}

void ChatSimulator::worker(std::string friend_name, unsigned seed) {
    std::mt19937 rng(seed);
    std::uniform_real_distribution<double> dist(min_seconds_, max_seconds_);
    while (running_.load()) {
        int total_ms = static_cast<int>(dist(rng) * 1000.0);
        int slept = 0;
        while (slept < total_ms && running_.load()) {
            int chunk = total_ms - slept;
            if (chunk > 100) chunk = 100;
            std::this_thread::sleep_for(std::chrono::milliseconds(chunk));
            slept += chunk;
        }
        if (!running_.load()) break;
        AutoMessage m;
        m.friend_name = friend_name;
        m.text = pick_message(seed);
        out_.push(m);
    }
}

std::string selftest_concurrency_json(const std::string& user) {
    std::vector<std::string> friends;
    if (!user.empty()) {
        std::vector<friends::Friend> list =
            friends::load(friends::friends_path(user));
        for (const auto& f : list) friends.push_back(f.user);
    }
    if (friends.empty()) {
        friends.push_back("alice");
        friends.push_back("bob");
        friends.push_back("carol");
    }

    ThreadSafeQueue<AutoMessage> queue;
    ChatSimulator sim(friends, queue, 1.0, 1.5);
    sim.start();

    long long processed = 0;
    auto deadline =
        std::chrono::steady_clock::now() + std::chrono::seconds(5);
    while (std::chrono::steady_clock::now() < deadline) {
        AutoMessage m;
        if (queue.try_pop(m)) {
            ++processed;
        } else {
            std::this_thread::sleep_for(std::chrono::milliseconds(20));
        }
    }
    sim.stop();

    AutoMessage drained;
    while (queue.try_pop(drained)) ++processed;

    std::ostringstream os;
    os << "{\"processed\": " << processed << "}";
    return os.str();
}

}

