#include "alias.hpp"
#include "auth.h"
#include "chat.hpp"
#include "concurrency.hpp"
#include "friends.hpp"
#include "search.hpp"

#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

namespace {

std::string read_text(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    if (!in) return std::string();
    std::ostringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

std::string trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

std::string upper(const std::string& s) {
    std::string out = s;
    for (char& c : out) {
        if (c >= 'a' && c <= 'z') c = static_cast<char>(c - 'a' + 'A');
    }
    return out;
}

std::vector<std::string> split_ws(const std::string& s) {
    std::vector<std::string> out;
    std::istringstream ss(s);
    std::string tok;
    while (ss >> tok) out.push_back(tok);
    return out;
}

bool ask(const std::string& p, std::string& out) {
    concurrency::prompt(p);
    return concurrency::read_line(out);
}

void run_search(const std::string& user, const std::string& keyword) {
    if (user.empty()) {
        concurrency::print_line("No user session");
        return;
    }
    if (keyword.empty()) {
        concurrency::print_line("Usage: /search <keyword>");
        return;
    }
    std::vector<search::Hit> hits = search::search_all(user, keyword);
    for (const auto& h : hits) {
        concurrency::print_line("[" + alias::resolve(user, h.friend_name) + "] " +
                                h.date + " | " +
                                search::highlight(h.text, keyword));
    }
}

std::string extract_string_field(const std::string& obj, const std::string& key) {
    std::string needle = "\"" + key + "\"";
    size_t p = obj.find(needle);
    if (p == std::string::npos) return "";
    p = obj.find(':', p + needle.size());
    if (p == std::string::npos) return "";
    p = obj.find('"', p);
    if (p == std::string::npos) return "";
    std::string out;
    for (size_t q = p + 1; q < obj.size(); ++q) {
        if (obj[q] == '\\' && q + 1 < obj.size()) {
            out += obj[q];
            out += obj[++q];
        } else if (obj[q] == '"') {
            break;
        } else {
            out += obj[q];
        }
    }
    return out;
}

