void run_friend_session(const std::string& username,
                        const std::string& sessionFile) {
    (void)sessionFile;
    const std::string path = friends::friends_path(username);
    auth:[secret redacted]

    concurrency::print_line("Welcome " + username);

    std::vector<std::string> sim_names;
    for (const auto& f : friends::load(path)) {
        sim_names.push_back(alias::resolve(username, f.user));
    }
    concurrency::ChatSimulator sim(sim_names, concurrency::message_queue(),
                                   3.0, 6.0);
    sim.start();

    while (true) {
        show_friend_menu();
        std::string choice;
        if (!ask("Action: ", choice)) break;
        std::string raw = trim(choice);
        std::string c = upper(raw);

        if (c.rfind("SET-ALIAS", 0) == 0) {
            std::vector<std::string> toks = split_ws(raw);
            if (toks.size() >= 3) {
                alias::set(username, toks[1], toks[2]);
                concurrency::print_line("Alias set");
            } else {
                concurrency::print_line("Usage: set-alias <friend> <alias>");
            }
        } else if (c.rfind("/SEARCH", 0) == 0) {
            size_t sp = raw.find(' ');
            std::string keyword =
                sp == std::string::npos ? std::string() : trim(raw.substr(sp + 1));
            run_search(username, keyword);
        } else if (c == "A") {
            std::string name;
            if (!ask("Friend: ", name)) break;
            name = trim(name);
            if (name.empty()) {
                concurrency::print_line("Friend name cannot be empty");
            } else if (friends::add(path, name)) {
                concurrency::print_line("Friend added");
            } else {
                concurrency::print_line("Friend already exists");
            }
        } else if (c == "R") {
            std::string name;
            if (!ask("Friend: ", name)) break;
            name = trim(name);
            if (friends::remove(path, name)) {
                concurrency::print_line("Friend removed");
            } else {
                concurrency::print_line("Friend not found");
            }
        } else if (c == "L") {
            std::vector<friends::Friend> list = friends::load(path);
            for (const auto& f : list) {
                concurrency::print_line("  - " + alias::resolve(username, f.user) +
                                        " [" + f.status + "]");
            }
        } else if (c == "C") {
            std::string name;
            if (!ask("Friend: ", name)) break;
            name = trim(name);
            if (!friends::exists(path, name)) {
                concurrency::print_line("Friend not found");
            } else {
                chat::run_chat(username, name, "data/scripts/bot_replies.json",
                               alias::resolve(username, name));
            }
        } else if (c == "Q") {
            concurrency::print_line("Logged out");
            break;
        } else {
            concurrency::print_line("Invalid choice");
        }
    }

    sim.stop();
}

